export function isAdult(age) {
  return Number.isInteger(age) && age > 18;
}

import assert from 'node:assert/strict';
import { isAdult } from './src/age.mjs';
for (const [age, expected] of [[17,false],[18,true],[19,true],['18',false],[NaN,false],[Infinity,false],[18.5,false]]) assert.equal(isAdult(age), expected);
console.log('AC-AGE-PASS');

